steps.script:
GameState.state["factions"]["2"].merge({"detachment": "Flyboyz"}, true)
StratagemManager.load_faction_stratagems_for_player(2)
var i := 0
for m in GameState.state.units["U_DEFFKOPTAS_A"].models:
	m["position"] = {"x": 1140.0 + i * 128.0, "y": 560.0}
	i += 1
tree.current_scene._recreate_unit_visuals()
return StratagemManager.get_stratagem("faction_ork_flyboyz_whirligig_evasion").get("implemented", false)

var p = PhaseManager.get_current_phase_instance()
var roll := -1
for d in p.dice_log:
	if str(d.get("type", "")) == "WHIRLIGIG EVASION":
		roll = int(d.get("roll", -1))
var cap := float(p.active_moves.get("U_DEFFKOPTAS_A", {}).get("move_cap_inches", -1.0))
if roll < 1 or roll > 6:
	return "no D6 in the dice log (riled up?)"
if absf(cap - roll) > 0.01:
	return "cap %s vs roll %d" % [str(cap), roll]
return "ok"
